        <ModelSelect />
      </AppHeader>
      <main className="min-h-0 flex-1">
        <Tabs
          active={activeTab}
          onChange={onTabChange}
          badges={
            reviewBadge === null
              ? undefined
              : {
                  review: (
                    <span className="rounded-full bg-sky-600 px-1.5 text-xs leading-5 text-white">
                      {reviewBadge}
                    </span>
                  ),
                }
          }
          panels={{
            editor: (
              <div className="flex h-full flex-col">
                <AskAiBar
                  focusRequested={askAiFocusRequested}
                  onFocusHandled={clearAskAiFocus}
                  quickActions={<PresetChips disabled={!canRun} onPick={runPreset} />}
                />
                <div className="min-h-0 flex-1">
                  <MarkdownEditor
                    value={content}
                    onChange={setContent}
                    onSelectionChange={setSelection}
                    dark={theme === 'dark'}
                    extensions={editorExtensions}
                  />
                </div>
              </div>
            ),
            preview: <MarkdownPreview content={content} />,
            review: (
              <div className="h-full overflow-y-auto">
                <AiReviewTab />
              </div>
            ),
          }}
        />
      </main>
      <CommandPalette
        open={paletteOpen}
        onOpenChange={setPaletteOpen}
        onSwitchTab={onTabChange}
        onAskAi={focusAskAi}
      />
    </div>
  )
}

function AppShell() {
  const [activeTab, setActiveTab] = useState<TabId>('editor')
